        self.index = index
        self.weight = weight
        self.children = []

def add_node(nodes, index, weight, parent_index):
    new_node = TreeNode(index, weight)
    nodes[parent_index].children.append(new_node)
    nodes[index] = new_node

def find_max_sequence(node, max_weight, max_length):
    stack = [(node, 1, node.weight)]
    while stack:
        current, length, current_sum = stack.pop()
        if current_sum > max_weight:
